import json, html
CRACK = "https://www.chiropractorpensacola.com/why-does-your-joint-pop-at-the-chiropractor/"
faqs = [
("What is chiropractic?", "Chiropractic is the evaluation of the neuromusculoskeletal system with treatment primarily targeting spinal misalignments, also known as subluxations, in order to increase range of motion, improve  function and remove nerve interference."),
("What conditions do chiropractors treat?", "Chiropractors treat many different conditions but they primarily focus on treating the musculoskeletal system. Some of the most common chiropractic treatments target neck and back pain, headaches, sciatica, whiplash injuries, joint point and postural issues."),
("What is a chiropractic adjustment?", "A chiropractic adjustment is the procedure performed by a chiropractor which repairs the function and stability of spinal structures. The adjustment enables the spinal structures to move into a better alignment which reduces nerve interference and allows the muscles, tendons and ligaments that have been compensating for the misalignment to relax reducing tension at the neck and back."),
("Is chiropractic treatment safe?", "Chiropractic treatments are very safe. Your Pensacola Chiropractor is a highly trained clinician who will perform a detailed examination prior to any treatment you receive to make sure you have no contraindications, or reasons you should not receive chiropractic treatment."),
("How many chiropractic treatments will I need?", "The amount of chiropractic treatments you will need are specific to each individual patient. Some factors include: is there an acute injury, is there an old injury that was not properly taken care of, are there degenerative spinal issues, does the type of work a person does or an activity they are regularly involved in continually aggravate the symptoms, does a person have postural issues, can a person perform the necessary exercises or is a person willing to perform the necessary exercises that will decrease the amount of time necessary to correct the problem."),
("What are the benefits of chiropractic care?", "Simply put the main benefit of chiropractic care at our office is an improved quality of life by restoring proper function of the body and eliminating or decreasing the frequency and severity of symptoms. This benefit comes from specific chiropractic treatments that are tailored to each patient and their specific needs. Many times this benefit comes from our treatment of neck and back injuries that help to eliminate pain. For some people we help them regain range of motion which decreases stiffness that was preventing them from enjoying physical activities."),
("Are there any risks associated with chiropractic treatment?", "The main risks associated with chiropractic treatment involve contraindications to treatment that patients have before they ever receive chiropractic treatment. This is why Your Pensacola Chiropractor will perform a thorough examination to determine if you have any condition that could be worsened with chiropractic treatment. Read this article that was written by Your Pensacola Chiropractor to help explain some of the more common contraindications to chiropractic treatment in more detail."),
("Are chiropractic adjustments painful?", "Most people do not experience pain with adjustments, but some do. Usually when adjustments are uncomfortable it is because the muscles and tissues around the area where the adjustment is being performed are already bruised, swollen or in a state of spasm. Fortunately Your Pensacola Chiropractor is able to effectively perform adjustments using different techniques or methods so we can find the best and most comfortable way to treat you!"),
("Why should I pick you as my chiropractor?", "Gilmore Chiropractic is Your Pensacola Chiropractor! You will receive extraordinary customer service along with an individual treatment plan that is made just for you and your specific needs. As Your Pensacola Chiropractor we are open late so you can receive the chiropractic treatment you need at a time that is convenient for you and your schedule!"),
("What is the crack sound during the adjustment?", "The crack sound that is often heard during a chiropractic adjustment is called a cavitation. You can read a more detailed description that Your Pensacola Chiropractor wrote about what causes the crack or popping sound, but it is caused by the formation of a gas bubble inside of a joint that occurs when the joint capsule is being stretched within its normal range of motion which decreases the pressure inside of the joint capsule. Most importantly you should know the cracking sound during a chiropractic adjustment is not caused by the breaking or tearing of any bones, discs or ligaments."),
]
def body(i, a):
    t = html.escape(a, quote=False).replace("  ", "&nbsp; ")
    if "more detailed description" in a:
        t = t.replace("more detailed description", f'<a href="{CRACK}">more detailed description</a>')
    return t
items = []
for i,(q,a) in enumerate(faqs):
    op = " open" if i==0 else ""
    items.append(f'<details class="faq"{op}><summary><span>{html.escape(q)}</span><i aria-hidden="true"></i></summary><div class="ans"><p>{body(i,a)}</p></div></details>')
tpl = open("_build/template.html").read()
open("index.html","w").write(tpl.replace("{{FAQS}}", "\n".join(items)))
schema = {"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in faqs]}
json.dump(schema, open("faq-schema.json","w"), indent=2, ensure_ascii=False)
